static void adjust_base(void *p,u32 pid){
 /* Baseline is captured once per exact base ID/stat, independently of pointer
    reuse. Cached absolute targets cannot compound on repeated DB lookups. */
 while(__atomic_exchange_n(&adjustment_lock,1,__ATOMIC_ACQUIRE)){}
 for(unsigned i=0;i<sizeof(adjustments)/sizeof(Adjustment);i++){
  const Adjustment *a=&adjustments[i];if(a->pid!=pid)continue;
  if(!adjustment_targets[i]){u32 v=0;if(!get_parameter(p,a->param,&v)||v>99)continue;v=v<a->below?v+a->delta:v;if(v>99)v=99;adjustment_targets[i]=v+1;}
  set_parameter(p,a->param,adjustment_targets[i]-1);
 }
 __atomic_store_n(&adjustment_lock,0,__ATOMIC_RELEASE);
}
