/* Mobile LoadBody helpers, never the PC-only LoadUniShirt stub.
   Original model fields stay intact. Only the requested actor/kit pair gets
   a separately named mesh with extended/folded cuffs and retained bare arms. */
#include "rolled-models.h"
typedef void(*RolledBodyFn)(void*,u32,u32,u32,u32,u32);
static RolledBodyFn rolled_detail_original,rolled_common_original;
static volatile u32 rolled_enabled,rolled_applies,rolled_common_applies;
