__attribute__((visibility("default"))) void configure_rolled_detail(uptr base,uptr p){(void)base;rolled_detail_original=(RolledBodyFn)p;}
__attribute__((visibility("default"))) void configure_rolled_common(uptr base,uptr p){(void)base;rolled_common_original=(RolledBodyFn)p;}
